});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const originalLineCount = invoice.lines.length;
  removeLine(invoice, 'DES-HOUR');

  assert.equal(invoice.lines.length, originalLineCount);
